#!/usr/bin/env node
// Generates src/styles/theme.generated.css from design/tokens.css.
// design/ is read-only after Gate A, so the Tailwind theme is derived from it
// rather than retyped. Run after any token change upstream:
//   node scripts/sync-tokens.mjs
// check-integrity runs this with --check and fails when the generated file
// is out of date.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const src = readFileSync(join(root, 'design/tokens.css'), 'utf8');
const outPath = join(root, 'src/styles/theme.generated.css');

const tokens = new Map();
const ingest = (css) => {
  const block = css.slice(css.indexOf(':root {') + 7, css.lastIndexOf('}'));
  for (const m of block.matchAll(/(--[a-z0-9-]+)\s*:\s*([^;]+);/g)) tokens.set(m[1], m[2].trim());
};
ingest(src);
// Post-Gate-A token decisions live in brand/tokens.overrides.css so design/
// stays untouched. Read second: a value there wins. Each one is logged in
// DESIGN-DEBT.md with its ADR.
const overridesPath = join(root, 'brand/tokens.overrides.css');
if (existsSync(overridesPath)) ingest(readFileSync(overridesPath, 'utf8'));

const need = (name) => {
  if (!tokens.has(name)) throw new Error(`design/tokens.css is missing ${name}`);
  return tokens.get(name);
};
const px = (name) => parseFloat(need(name));
const rem = (n) => `${+(n / 16).toFixed(4)}rem`;

// Fluid type between the 390 and 1440 artboards. Sizes are emitted in rem so
// browser text zoom still works.
const fluid = (minPx, maxPx) => {
  if (minPx === maxPx) return rem(minPx);
  const slope = (maxPx - minPx) / (1440 - 390);
  const intercept = minPx - slope * 390;
  return `clamp(${rem(minPx)}, ${rem(intercept)} + ${+(slope * 100).toFixed(4)}vw, ${rem(maxPx)})`;
};

const lines = [];
const out = (k, v) => lines.push(`  ${k}: ${v};`);

lines.push('  /* Reset the Tailwind defaults that the brand does not use. */');
out('--color-*', 'initial');
out('--font-*', 'initial');
out('--text-*', 'initial');
out('--radius-*', 'initial');
out('--shadow-*', 'initial');
out('--breakpoint-*', 'initial');

lines.push('', '  /* color (design/tokens.css, verbatim) */');
for (const [k, v] of tokens) if (k.startsWith('--color-')) out(k, v);
out('--color-white', need('--color-surface'));
out('--color-transparent', 'transparent');
out('--color-current', 'currentColor');

lines.push('', '  /* radius and elevation */');
for (const [k, v] of tokens) if (k.startsWith('--radius-') || k.startsWith('--shadow-')) out(k, v);

lines.push('', '  /* type families, with the metric-matched fallback faces from fonts.css */');
out('--font-heading', '"Archivo", "Archivo Fallback", sans-serif');
out('--font-body', '"Manrope", "Manrope Fallback", sans-serif');

lines.push('', '  /* type scale, fluid from 390 to 1440 */');
const scale = ['display', 'h1', 'h2', 'h3', 'h4', 'body-lg', 'body', 'body-sm'];
for (const name of scale) {
  out(`--text-${name}`, fluid(px(`--text-${name}-mobile`), px(`--text-${name}-desktop`)));
  const lh = tokens.get(`--leading-${name}`) ?? (name.startsWith('body') ? need('--leading-body') : null);
  if (lh) out(`--text-${name}--line-height`, lh);
}
out('--text-eyebrow', rem(px('--text-eyebrow')));
out('--text-eyebrow--line-height', '1');
out('--text-eyebrow--letter-spacing', need('--tracking-eyebrow'));
out('--tracking-heading', need('--tracking-heading'));
out('--tracking-eyebrow', need('--tracking-eyebrow'));

lines.push('', '  /* breakpoints: Tailwind defaults plus the 360 phone, 480 button and 900 nav lines */');
out('--breakpoint-xs', '22.5rem');
out('--breakpoint-btn', '30rem');
out('--breakpoint-sm', '40rem');
out('--breakpoint-md', '48rem');
out('--breakpoint-nav', '56.25rem');
out('--breakpoint-lg', '64rem');
out('--breakpoint-xl', '80rem');
out('--breakpoint-2xl', '96rem');

lines.push('', '  /* layout */');
out('--container-site', need('--container'));

lines.push('', '  /* everything else, passed through for var() use in components */');
const passthrough = [...tokens.keys()].filter(
  (k) =>
    !k.startsWith('--color-') &&
    !k.startsWith('--radius-') &&
    !k.startsWith('--shadow-') &&
    !k.startsWith('--text-') &&
    !k.startsWith('--font-') &&
    !k.startsWith('--leading-') &&
    !k.startsWith('--tracking-') &&
    k !== '--container',
);
for (const k of passthrough) out(k.replace(/^--/, '--rc-'), tokens.get(k));

const css = `/* GENERATED by scripts/sync-tokens.mjs from design/tokens.css and brand/tokens.overrides.css. Do not edit by hand. */
@theme static {
${lines.join('\n')}
}
`;

if (process.argv.includes('--check')) {
  const current = existsSync(outPath) ? readFileSync(outPath, 'utf8') : '';
  if (current !== css) {
    console.error('theme.generated.css is out of date with design/tokens.css. Run: node scripts/sync-tokens.mjs');
    process.exit(1);
  }
  console.log('theme.generated.css is in sync with design/tokens.css');
} else {
  writeFileSync(outPath, css);
  console.log(`wrote ${outPath} (${tokens.size} tokens)`);
}
